const VS=`#version 300 es
in vec3 aPosition;in vec3 aNormal;uniform mat4 uMvp;uniform mat4 uModel;uniform mat3 uNormalMatrix;out vec3 vNormal;out vec3 vWorld;
void main(){vec4 w=uModel*vec4(aPosition,1.0);vWorld=w.xyz;vNormal=normalize(uNormalMatrix*aNormal);gl_Position=uMvp*vec4(aPosition,1.0);}`;
const FS=`#version 300 es
precision highp float;in vec3 vNormal;in vec3 vWorld;uniform vec3 uColor;uniform vec3 uViewPos;uniform vec3 uLightPos[3];uniform vec3 uLightColor[3];uniform float uLightPower[3];uniform float uLight;uniform float uMetallic;uniform float uRoughness;uniform float uEmission;uniform float uFlat;out vec4 outColor;
void main(){vec3 n=normalize(vNormal),v=normalize(uViewPos-vWorld);float e=mix(96.0,5.0,clamp(uRoughness,.04,1.0));vec3 c=uColor*(.17+.12*uLight);for(int i=0;i<3;i++){vec3 delta=uLightPos[i]-vWorld;float dist=max(length(delta),.25);vec3 l=delta/dist,h=normalize(l+v);float d=max(dot(n,l),0.0),atten=1.0/(1.0+.12*dist+.025*dist*dist);float spec=pow(max(dot(n,h),0.0),e)*(.08+uMetallic*.62);c+=uColor*d*uLightPower[i]*atten*uLightColor[i]*uLight+vec3(spec)*mix(.72,1.18,uMetallic)*atten*uLightPower[i]*uLightColor[i];}if(uFlat>.5)c=uColor;c+=uColor*uEmission;outColor=vec4(c,1.0);}`;
function compile(gl,type,src){const s=gl.createShader(type);gl.shaderSource(s,src);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw new Error(gl.getShaderInfoLog(s)||'Shader compile failed');return s;}
function makeProgram(gl){const p=gl.createProgram();gl.attachShader(p,compile(gl,gl.VERTEX_SHADER,VS));gl.attachShader(p,compile(gl,gl.FRAGMENT_SHADER,FS));gl.linkProgram(p);if(!gl.getProgramParameter(p,gl.LINK_STATUS))throw new Error(gl.getProgramInfoLog(p)||'Shader link failed');return p;}
function tri(o,a,b,c,na,nb,nc){[a,b,c].forEach((p,i)=>{o.p.push(...p);o.n.push(...[na,nb,nc][i]);});}
